const data = ($json.data || {});
const errors = $json.errors || null;
const threshold = parseInt($env.HUNTER_MIN_REMAINING_REQUESTS || '100', 10);

// Unreachable / auth error / malformed response
if (errors || !data.requests) {
  return [{ json: {
    alert: true,
    channel: $env.SLACK_ALERT_CHANNEL_ID,
    text: `:warning: *Hunter.io balance check failed* — cannot verify remaining requests.\n\n*Likely cause*: API key invalid, Hunter outage, or network issue.\n*Action*: Check Hunter status and HUNTER_API_KEY in docker-compose.yml. Manually review https://hunter.io/users/subscription before the 6 AM P2.1 run.\n*Response snippet*: \`\`\`${JSON.stringify($json).slice(0, 300)}\`\`\``
  }}];
}

const searches = data.requests.searches || {};
const used = Number(searches.used || 0);
const available = Number(searches.available || 0);
const remaining = Math.max(0, available - used);
const plan = data.plan_name || 'Unknown';

if (remaining >= threshold) {
  // Healthy -- no alert
  return [{ json: { alert: false, remaining, threshold, plan } }];
}

return [{ json: {
  alert: true,
  channel: $env.SLACK_ALERT_CHANNEL_ID,
  text: `:rotating_light: *Hunter.io balance low*\n\n*Remaining searches*: ${remaining} of ${available}\n*Used this period*: ${used}\n*Threshold*: ${threshold}\n*Plan*: ${plan}\n\n*Action*: Top up at https://hunter.io/users/subscription. Until topped up, P2.1 will drop leads that can't be enriched at >= 0.9 confidence.`
}}];

// Apify /v2/users/me shape has varied across plan tiers and API versions.
// Extract defensively across known field names; treat missing fields as
// 'unknown plan' which we also alert on so Kevon can verify manually.

const data = ($json.data || {});
const errors = $json.error || $json.errors || null;
const threshold = parseFloat($env.APIFY_MIN_USD_BALANCE || '5');

if (errors || !data || Object.keys(data).length === 0) {
  return [{ json: {
    alert: true,
    channel: $env.SLACK_ALERT_CHANNEL_ID,
    text: `:warning: *Apify balance check failed* — cannot verify remaining USD credits.\n\n*Likely cause*: API token invalid, Apify outage, or network issue.\n*Action*: Check Apify status and APIFY_TOKEN in docker-compose.yml. Manually review https://console.apify.com/billing before the 6 AM P2.1 run.\n*Response snippet*: \`\`\`${JSON.stringify($json).slice(0, 300)}\`\`\``
  }}];
}

const plan = data.plan || {};
const usage = data.usage || data.usageCycle || {};

const limitUsd = Number(
  plan.monthlyUsageLimitUsd != null ? plan.monthlyUsageLimitUsd :
  plan.maxMonthlyUsageUsd     != null ? plan.maxMonthlyUsageUsd :
  0
);
const usedUsd = Number(
  usage.usageUsd                      != null ? usage.usageUsd :
  usage.currentBillingPeriodUsageUsd  != null ? usage.currentBillingPeriodUsageUsd :
  0
);

// If we couldn't find a limit, plan is likely Enterprise/custom -- don't false-alarm.
if (!limitUsd) {
  return [{ json: { alert: false, reason: 'unknown_limit', plan_id: plan.id || 'unknown' } }];
}

const remainingUsd = Math.max(0, limitUsd - usedUsd);
if (remainingUsd >= threshold) {
  return [{ json: { alert: false, remainingUsd, threshold, plan: plan.id || 'unknown' } }];
}

return [{ json: {
  alert: true,
  channel: $env.SLACK_ALERT_CHANNEL_ID,
  text: `:rotating_light: *Apify balance low*\n\n*Remaining*: $${remainingUsd.toFixed(2)} USD\n*Used this period*: $${usedUsd.toFixed(2)}\n*Monthly limit*: $${limitUsd.toFixed(2)}\n*Threshold*: $${threshold.toFixed(2)}\n*Plan*: ${plan.id || 'unknown'}\n\n*Action*: Top up or upgrade at https://console.apify.com/billing. Until then, P2.1's Crunchbase + Wellfound actors may fail to run and drop today's lead sourcing.`
}}];
